export default {
  id: 'calculator',
  name: 'Calculator',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({ kind: 'tool', tool: {
      name: 'sum_values',
      version: '1.0.0',
      description: 'Sum an array of numeric values and return their total.',
      permissions: [],
      sideEffect: 'none',
      parameters: {
        type: 'object',
        properties: {
          numbers: { type: 'array', items: { type: 'number' }, description: 'Numbers to add' }
        },
        required: ['numbers'],
        additionalProperties: false
      },
      outputSchema: {
        type: 'object',
        properties: { sum: { type: 'number' } },
        required: ['sum']
      },
      async handler(args: unknown, tctx: unknown) {
        void tctx;
        const { numbers } = args as { numbers: number[] };
        if (!Array.isArray(numbers) || !numbers.every((n) => typeof n === 'number' && Number.isFinite(n))) {
          return { ok: false, error: 'numbers must be an array of finite numbers' };
        }
        const sum = numbers.reduce((a, b) => a + b, 0);
        return { ok: true, data: { sum } };
      }
    }});
  }
};

